#!/usr/bin/env bash
# QEMU ESP32-S3 feasibility bench (walk modes 2026-11-09). Builds the Motion
# scenarios of qemu_motion/ twice on the production sources of THIS tree: host
# (g++) and ESP32-S3 (arduino-cli, Arduino ESP32 3.3.11), runs the second in
# Espressif QEMU (-icount shift=3, deterministic) and compares the per-scenario
# RAW frame digests. Never a prerequisite to build or flash MATDOG; no hardware.
# Usage: run_qemu_motion.sh [--profile] [out-dir]   (QEMU: $MATDOG_QEMU or ~/MATDOG/tools/qemu-esp)
#   --profile: count the double-precision libgcc and libm calls of the Motion
#   objects per scenario (-Wl,--wrap) and microbenchmark one call of each.
#   --diag: build with MATDOG_DIAG_PREEMPTION and check its other-task time
#   against a synthetic preemptor on the Motion core (diagnostic build only).
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)";sketch="$(cd "$here/../.." && pwd)"
profile=0;diag=0;if [ "${1:-}" = "--profile" ];then profile=1;shift;fi;if [ "${1:-}" = "--diag" ];then diag=1;shift;fi
out="${1:-$(mktemp -d /tmp/matdog-qemu.XXXXXX)}";mkdir -p "$out"
qemu="${MATDOG_QEMU:-$(ls -d "$HOME"/MATDOG/tools/qemu-esp/esp_develop_*/*/bin 2>/dev/null | tail -1)/qemu-system-xtensa}"
src=("$sketch/src/simple/SimpleMotion.cpp" "$sketch/src/servo/ServoPopulation.cpp")
for n in BodyPose ContactMode FootContact Gait GaitTiming ImuAttitude LegKinematics LegInverseKinematics StandTrajectory TiltCompensation TiltedContactIk; do src+=("$sketch/src/motion/$n.cpp"); done
inc=(-I "$sketch/src/simple" -I "$sketch/src/motion")
"${CXX:-g++}" -std=c++17 -O2 -w -I "$sketch/scripts/tests/simple_host_stub" "${inc[@]}" "$here/qemu_motion/host_main.cpp" "${src[@]}" -o "$out/host"
"$out/host" > "$out/host.txt"
mkdir -p "$out/qemu_motion";cp "$here/qemu_motion/qemu_motion.ino" "$here/qemu_motion/motion_scenarios.h" "$here/qemu_motion/qemu_profile.cpp" "$out/qemu_motion/"
k=0;for f in "${src[@]}"; do printf '// Generated by run_qemu_motion.sh: one production source, unchanged.\n#include "%s"\n' "$f" > "$out/qemu_motion/motion_src_$k.cpp";k=$((k+1));done
"${ARDUINO_CLI:-$HOME/.local/bin/arduino-cli}" compile --fqbn esp32:esp32:esp32s3:CDCOnBoot=default,PSRAM=disabled,FlashMode=dio,FlashSize=4M \
  --build-property "compiler.cpp.extra_flags=-I$sketch/src/simple -I$sketch/src/motion$([ $profile = 1 ] && echo ' -DMOTION_PROFILE')$([ $diag = 1 ] && echo ' -DMATDOG_DIAG_PREEMPTION')" \
  --build-property "compiler.c.elf.extra_flags=-Wl,--wrap=esp_timer_get_time$([ $profile = 1 ] && for f in __adddf3 __subdf3 __muldf3 __divdf3 __ltdf2 __gtdf2 __ledf2 __gedf2 __eqdf2 __nedf2 __unorddf2 __floatsidf __floatunsidf __fixdfsi __extendsfdf2 __truncdfsf2 sin cos atan2 asin acos atan sqrt hypot floor ceil fmod remainder lround; do printf ' -Wl,--wrap=%s' $f; done)" \
  --output-dir "$out/build" "$out/qemu_motion" > "$out/compile.txt" 2>&1 || { tail -30 "$out/compile.txt";exit 1; }
cp "$out/build/qemu_motion.ino.merged.bin" "$out/flash.bin"
timeout "${QEMU_TIMEOUT:-3000}" "$qemu" -nographic -machine esp32s3 -icount shift=3 -drive file="$out/flash.bin",if=mtd,format=raw -serial mon:stdio > "$out/qemu.txt" 2>&1 &
pid=$!;while kill -0 $pid 2>/dev/null; do if grep -q '^DONE' "$out/qemu.txt" 2>/dev/null; then kill $pid;break;fi;sleep 5;done;wait $pid 2>/dev/null||true
tr -d '\r' < "$out/qemu.txt" | grep -E '^(PLATFORM|SCENARIO|STACK|DONE|PROFILE|MICROBENCH|DIAG_PREEMPTION)' > "$out/target.txt" || true
echo "== host";cat "$out/host.txt";echo "== esp32s3-qemu";cat "$out/target.txt"
echo "== comparison (frames, digest, max step, state, reason, first fault, exit)"
paste -d'\n' <(grep ^SCENARIO "$out/host.txt" | awk '{print $2,$3,$4,$5,$6,$7,$8,$9,$10}') <(grep ^SCENARIO "$out/target.txt" | awk '{print $2,$3,$4,$5,$6,$7,$8,$9,$10}') | paste - - | \
  awk -F'\t' '{print ($1==$2?"SAME ":"DIFF ") $1 (($1==$2)?"":"  |  target: " $2)}'
